content:
{
  "findings": [
    {
      "title": "Exclusion criterion 1 contradicts inclusion criterion 7a",
      "page": 39,
      "quote": "Neutrophil count at or above 1200 /mm3.",
      "severity": "critical"
    },
    {
      "title": "Inclusion criterion 4c requires progression in previously radiated lesion, but exclusion criterion 2 prohibits recent radiation",
      "page": 38,
      "quote": "Documented disease progression in any lesion that was previously radiated in order to serve as a target lesion.",
      "severity": "major"
    },
    {
      "title": "Inclusion criterion 11 requires negative serum pregnancy test before dosing, but Section 4.3 allows urine test",
      "page": 39,
      "quote": "Women of childbearing potential must have negative serum pregnancy test before dosing at W1D1",
      "severity": "major"
    },
    {
      "title": "Inclusion criterion 7a requires WBC ≥ 2000/mm3, but exclusion criterion 1 excludes only neutrophil count ≥ 1200/mm3, not WBC",
      "page": 39,
      "quote": "white blood cells ≥ 2000/mm3",
      "severity": "minor"
    },
    {
      "title": "Inclusion criterion 4c requires progression in previously radiated lesion, but exclusion criterion 2 prohibits radiation within 2 weeks before first dose",
      "page": 40,
      "quote": "Received radiation therapy (or other nonsystemic therapy) within 2 weeks before first dose of study treatment on W1D1.",
      "severity": "major"
    },
    {
      "title": "Inclusion criterion 3b requires PD within 12 weeks of last dose, but confirmatory assessment may serve as Baseline if completed within 30 days before start of treatment",
      "page": 38,
      "quote": "Have PD (according to RECIST v1.1) within 12 weeks of the last dose of a PD-1 blocking antibody",
      "severity": "minor"
    },
    {
      "title": "Inclusion criterion 5 allows archival sample if no intervening therapy, but does not specify time window for archival sample",
      "page": 38,
      "quote": "A fresh tissue biopsy (within 90 days before the start of study treatment) is preferred but an archival sample is acceptable (as a substitute) if no intervening therapy was received.",
      "severity": "minor"
    },
    {
      "title": "Section 4.3.1 requires FSH > 40 mIU/mL on 2 measurements 2 months apart, but does not specify if these must be before W1D1",
      "page": 41,
      "quote": "Females with less than 12 months of amenorrhea must have a serum follicle stimulating hormone (FSH) level > 40 mIU/mL on 2 measurements performed 2 months apart",
      "severity": "minor"
    },
    {
      "title": "Section 4.4 prohibits live/attenuated vaccines until 100 days post last dose, but Section 4.4.1 allows viral vector or mRNA vaccines within 1 week of CMP-001 injection",
      "page": 42,
      "quote": "Any live / attenuated vaccine (eg, varicella, zoster, yellow fever, rotavirus, oral polio and measles, mumps, rubella [MMR]) during treatment and until 100 days post last dose.",
      "severity": "major"
    },
    {
      "title": "Section 4.5 says treatment discontinuation if subject does not restart within 12 weeks, but also says permanent discontinuation if > 12 weeks",
      "page": 43,
      "quote": "Treatment discontinuation is defined as any subject who stops receiving study treatment and does not restart within 12 weeks. Subjects who permanently discontinue (> 12 weeks) CMP-001 or nivolumab, may not be retreated with the discontinued study treatment in this study.",
      "severity": "minor"
    },
    {
      "title": "Section 5.1.1 says nivolumab 360 mg IV at W1D1 and Q3W thereafter, but Section 5.1.1.1 says 360 mg Q3W is under evaluation, not approved",
      "page": 45,
      "quote": "Subjects will receive CMP-001 10 mg IT injection followed by nivolumab 360 mg IV at W1D1 and Q3W thereafter",
      "severity": "minor"
    },
    {
      "title": "Section 5.1.2.1.1 says subjects with adrenal insufficiency must receive stress-dose steroids before and after each CMP-001 injection, but Section 4.4 says systemic corticosteroids > 10 mg/day are not permitted at enrollment",
      "page": 48,
      "quote": "All subjects with adrenal insufficiency must receive prophylactic stress-dose steroids (eg, 50 to 100 mg hydrocortisone or equivalent orally every 8 hours) before and for 24 to 48 hours after each CMP-001 injection.",
      "severity": "major"
    }
  ]
}
